 document.querySelectorAll('#home .rail .sleeve-art,#home .live-record').forEach(record=>{const sheen=document.createElement('span');sheen.className='record-sheen';sheen.setAttribute('aria-hidden','true');record.append(sheen)});
 const tea=document.querySelector('#home .contact-matcha [clip-path]');if(tea){const wash=document.createElementNS('http://www.w3.org/2000/svg','path');wash.classList.add('matcha-blend');wash.setAttribute('d','M20 44Q50 36 80 44V105H20Z');wash.setAttribute('fill','#91a75f');tea.append(wash)}
 // Tiny short-lived flecks originate at the stylus tip, using the arm's actual SVG transform.
 const canvas=document.createElement('canvas');canvas.className='stylus-dust';canvas.setAttribute('aria-hidden','true');document.body.append(canvas);const ctx=canvas.getContext('2d'),particles=[];let last=0,burst=0;
 const reduce=matchMedia('(prefers-reduced-motion: reduce)');function resize(){canvas.width=innerWidth;canvas.height=innerHeight}addEventListener('resize',resize);resize();
